function date(t,clock=false){const d=new Date(parseTime(/^\d{4}-\d{2}-\d{2}$/.test(t)?t+'T12:00:00Z':t));return Number.isFinite(+d)?d.toLocaleString('nb-NO',{day:'2-digit',month:'short',...(clock?{hour:'2-digit',minute:'2-digit'}:{year:'numeric'}),timeZone:'Europe/Oslo'}):'Ukjent tidspunkt';}
