function drawNotice(){const stale=Date.now()-parseTime(D.bygd)>36*3600000;const missing=S.favorite.filter(n=>!byId.has(n));let messages=[];if(!navigator.onLine)messages.push('Du er utan nett. Viser sist lagra data frå '+date(D.bygd,true)+'. Kartfliser kan mangle.');else if(stale)messages.push('Dataa er gamle: siste publisering var '+date(D.bygd,true)+'. Oppdatering er forseinka.');if(sourceWarning)messages.push(sourceWarning);if(missing.length)messages.push(missing.length+' favorittanlegg er ikkje i det siste registeret. Det betyr ikkje at dei har null hendingar.');const failed=Object.entries(D.kjelder||{}).filter(([,s])=>s.status==='feila'||s.status==='delvis');if(failed.length)messages.push(failed.length+' datakjelder er ufullstendige. Sjå datastatus for detaljar.');$('notice').innerHTML=messages.map(t=>'<div class="banner">'+esc(t)+'<button data-view="kjelder">Datastatus ↗</button></div>').join('');$('update-badge').textContent=(stale?'Sist henta ':'Oppdatert ')+age(D.bygd);$('update-badge').classList.toggle('stale',stale);}
