function mapHtml(){return '<div class="map-card"><div class="map-toolbar"><h2>'+icon('map')+' Anlegg og fartøy</h2><span class="caption">'+(S.region===null?'NORSKEKYSTEN':'PRODUKSJONSOMRÅDE '+S.region)+'</span></div><div class="map-stage"><div id="map" aria-label="Kart over oppdrettsanlegg og fartøy"></div><div class="map-floating">'+[['kart','Kart'],['sjokart','Sjøkart'],['enkelt','Område']].map(([k,n])=>'<button data-base="'+k+'" class="'+(S.base===k?'active':'')+'" aria-pressed="'+(S.base===k)+'">'+n+'</button>').join('')+'</div><div class="map-controls"><button data-zoom="in" aria-label="Zoom inn">+</button><button data-zoom="out" aria-label="Zoom ut">−</button><button data-zoom="fit" aria-label="Vis alle treff" title="Vis alle treff">⌖</button></div><div class="map-layers"><h3>KARTLAG</h3>'+[['sites','Anlegg og lusetal'],['boats','Fartøysposisjonar'],['areas','Trafikklysområde'],['pd','PD-kontrollsoner'],['ila','ILA-kontrollsoner'],['pdarea','Nasjonale PD-område']].map(([k,n])=>'<label><input type="checkbox" data-layer="'+k+'" '+(S.layers[k]?'checked':'')+'>'+n+'</label>').join('')+'<small>AIS: '+esc(age(D.aisTid))+'<br>'+(aisRefreshed?'Oppdatert i denne økta':'Dagleg stillbilete')+'</small></div></div><div class="map-legend">'+[['over','Ved/over grensa'],['near','Nær grensa'],['ok','Under grensa'],['unknown','Utan tal'],['boat','Fartøy'],['pd','PD-sone'],['ila','ILA-sone']].map(([k,n])=>'<span><i class="dot '+k+'"></i>'+n+'</span>').join('')+'</div><p class="map-footnote">Lusetal: veke '+D.veke.uke+', '+D.veke.aar+'. Fartøy kan ha flytta seg. Kartet er ikkje eit navigasjonsverktøy.</p>'+'<p id="traffic-light-note" class="map-footnote" '+(S.layers.areas||S.base==='enkelt'?'':'hidden')+'>Trafikklys 2026–27: raudt = nedjustering, gult = uendra, grønt = mogleg vekst. Fargane gjeld områda, ikkje diagnosen på kvart anlegg.</p>'+'</div>';}
